mapper.select:
select config_value
from sys_config
where tenant_id = #{tenantId}
  and config_key = #{configKey}
  and config_scope = #{configScope}
  and deleted = 0
order by id desc
limit 1

select * from sys_config where deleted = 0 and config_scope = #{configScope} and config_key in
#{key}
and (tenant_id = #{tenantId} or tenant_id is null) order by case when tenant_id = #{tenantId} then 0 when tenant_id is null then 1 else 2 end, id desc
